// ---------------------------------------------------------------- maps

/// Per-relkey version vector {device_id: counter} (§2.6). Missing components read as 0; zero components are never stored — decoders drop them so `{a:1,b:0}` equals `{a:1}`.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(from = "BTreeMap<DeviceId, u32>", into = "BTreeMap<DeviceId, u32>")]
pub struct VersionVector(BTreeMap<DeviceId, u32>);

impl VersionVector {
    pub fn new() -> Self {
        Self::default()
    }
    /// Missing components read as 0.
    pub fn get(&self, k: &DeviceId) -> u32 {
        self.0.get(k).copied().unwrap_or(0)
    }
    /// Sets a component; a zero removes it (zero components are never stored).
    pub fn set(&mut self, k: DeviceId, v: u32) {
        if v == 0 {
            self.0.remove(&k);
        } else {
            self.0.insert(k, v);
        }
    }
    /// Increments a component by one (one admitted upload = one version, §2.6).
    ///
    /// Saturates at the counter maximum; a saturated bump would silently produce a "new" version
    /// comparing `Equal` to the old one, so debug builds assert instead.
    pub fn bump(&mut self, k: &DeviceId) {
        let slot = self.0.entry(k.clone()).or_insert(0);
        debug_assert!(*slot < u32::MAX, "version vector component overflow for {k}: bump would not be monotonic");
        *slot = slot.saturating_add(1);
    }
    /// Element-wise maximum.
    pub fn merge(&mut self, other: &Self) {
        for (k, &v) in &other.0 {
            if v == 0 {
                continue;
            }
            let slot = self.0.entry(k.clone()).or_insert(0);
            *slot = (*slot).max(v);
        }
    }
    pub fn iter(&self) -> std::collections::btree_map::Iter<'_, DeviceId, u32> {
        self.0.iter()
    }
    pub fn len(&self) -> usize {
        self.0.len()
    }
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
    /// Ordering of two vectors: Equal, Greater (self dominates), Less, or Concurrent (§2.6).
    pub fn compare(&self, other: &Self) -> VvOrder {
        let mut ge = true;
        let mut le = true;
        let keys: std::collections::BTreeSet<&DeviceId> = self.0.keys().chain(other.0.keys()).collect();
        for k in keys {
            let a = self.get(k);
            let b = other.get(k);
            if a < b {
                ge = false;
            }
            if a > b {
                le = false;
            }
        }
        match (ge, le) {
            (true, true) => VvOrder::Equal,
            (true, false) => VvOrder::Greater,
            (false, true) => VvOrder::Less,
            (false, false) => VvOrder::Concurrent,
        }
    }
}

impl From<BTreeMap<DeviceId, u32>> for VersionVector {
    fn from(map: BTreeMap<DeviceId, u32>) -> Self {
        map.into_iter().collect()
    }
}
impl From<VersionVector> for BTreeMap<DeviceId, u32> {
    fn from(v: VersionVector) -> Self {
        v.0
    }
}
impl FromIterator<(DeviceId, u32)> for VersionVector {
    fn from_iter<T: IntoIterator<Item = (DeviceId, u32)>>(iter: T) -> Self {
        let mut map = BTreeMap::new();
        for (k, v) in iter {
            if v == 0 {
                continue;
            }
            let slot = map.entry(k).or_insert(0);
            *slot = (*slot).max(v);
        }
        Self(map)
    }
}

/// Highest contiguously-applied journal seq per peer device.
pub type AppliedCursors = BTreeMap<DeviceId, u64>;

/// Result of comparing two version vectors (§2.6).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VvOrder {
    Equal,
    Greater,
    Less,
    Concurrent,
}

